CREATE TYPE "FamilyRole" AS ENUM ('OWNER', 'ADMIN', 'MEMBER');
CREATE TYPE "ShoppingListStatus" AS ENUM ('DRAFT', 'ACTIVE', 'COMPLETED', 'ARCHIVED');
CREATE TABLE "users" ("id" UUID NOT NULL,"name" VARCHAR(120) NOT NULL,"email" VARCHAR(255) NOT NULL,"password_hash" VARCHAR(255) NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE TABLE "auth_sessions" ("id" UUID NOT NULL,"user_id" UUID NOT NULL,"refresh_token_hash" VARCHAR(255) NOT NULL,"expires_at" TIMESTAMPTZ(6) NOT NULL,"revoked_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "auth_sessions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "auth_sessions_refresh_token_hash_key" ON "auth_sessions"("refresh_token_hash");
CREATE INDEX "auth_sessions_user_id_expires_at_idx" ON "auth_sessions"("user_id","expires_at");
CREATE TABLE "families" ("id" UUID NOT NULL,"name" VARCHAR(120) NOT NULL,"currency_code" CHAR(3) NOT NULL DEFAULT 'COP',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "families_pkey" PRIMARY KEY ("id"));
CREATE TABLE "family_members" ("id" UUID NOT NULL,"family_id" UUID NOT NULL,"user_id" UUID NOT NULL,"role" "FamilyRole" NOT NULL DEFAULT 'MEMBER',"joined_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "family_members_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "family_members_family_id_user_id_key" ON "family_members"("family_id","user_id");
CREATE INDEX "family_members_user_id_idx" ON "family_members"("user_id");
CREATE TABLE "categories" ("id" UUID NOT NULL,"name" VARCHAR(100) NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "categories_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "categories_name_key" ON "categories"("name");
CREATE TABLE "products" ("id" UUID NOT NULL,"name" VARCHAR(180) NOT NULL,"description" TEXT,"category_id" UUID,"base_unit" VARCHAR(16) NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "products_pkey" PRIMARY KEY ("id"));
CREATE INDEX "products_name_idx" ON "products"("name");
CREATE INDEX "products_category_id_idx" ON "products"("category_id");
CREATE TABLE "family_products" ("id" UUID NOT NULL,"family_id" UUID NOT NULL,"product_id" UUID NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "family_products_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "family_products_family_id_product_id_key" ON "family_products"("family_id","product_id");
CREATE TABLE "supermarkets" ("id" UUID NOT NULL,"name" VARCHAR(120) NOT NULL,"country_code" CHAR(2) NOT NULL DEFAULT 'CO',"website" VARCHAR(255),"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "supermarkets_pkey" PRIMARY KEY ("id"));
CREATE INDEX "supermarkets_name_idx" ON "supermarkets"("name");
CREATE TABLE "family_supermarkets" ("id" UUID NOT NULL,"family_id" UUID NOT NULL,"supermarket_id" UUID NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "family_supermarkets_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "family_supermarkets_family_id_supermarket_id_key" ON "family_supermarkets"("family_id","supermarket_id");
CREATE TABLE "shopping_lists" ("id" UUID NOT NULL,"family_id" UUID NOT NULL,"created_by_id" UUID,"name" VARCHAR(150) NOT NULL,"status" "ShoppingListStatus" NOT NULL DEFAULT 'DRAFT',"currency_code" CHAR(3) NOT NULL DEFAULT 'COP',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,"completed_at" TIMESTAMPTZ(6),CONSTRAINT "shopping_lists_pkey" PRIMARY KEY ("id"));
CREATE INDEX "shopping_lists_family_id_status_idx" ON "shopping_lists"("family_id","status");
CREATE TABLE "shopping_list_items" ("id" UUID NOT NULL,"shopping_list_id" UUID NOT NULL,"product_id" UUID NOT NULL,"quantity" DECIMAL(12,3) NOT NULL,"quantity_unit" VARCHAR(16) NOT NULL,"checked" BOOLEAN NOT NULL DEFAULT false,"sort_order" INTEGER NOT NULL DEFAULT 0,"notes" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "shopping_list_items_pkey" PRIMARY KEY ("id"),CONSTRAINT "shopping_list_items_quantity_check" CHECK ("quantity" > 0));
CREATE INDEX "shopping_list_items_shopping_list_id_sort_order_idx" ON "shopping_list_items"("shopping_list_id","sort_order");
CREATE INDEX "shopping_list_items_product_id_idx" ON "shopping_list_items"("product_id");
CREATE TABLE "product_prices" ("id" UUID NOT NULL,"family_id" UUID NOT NULL,"product_id" UUID NOT NULL,"supermarket_id" UUID NOT NULL,"shopping_list_item_id" UUID,"price" DECIMAL(14,2) NOT NULL,"currency_code" CHAR(3) NOT NULL DEFAULT 'COP',"package_quantity" DECIMAL(12,3) NOT NULL DEFAULT 1,"package_unit" VARCHAR(16) NOT NULL DEFAULT 'unit',"observed_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"recorded_by_id" UUID,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "product_prices_pkey" PRIMARY KEY ("id"),CONSTRAINT "product_prices_price_check" CHECK ("price" > 0),CONSTRAINT "product_prices_package_quantity_check" CHECK ("package_quantity" > 0));
CREATE INDEX "product_prices_family_id_product_id_supermarket_id_observed_at_idx" ON "product_prices"("family_id","product_id","supermarket_id","observed_at");
CREATE INDEX "product_prices_shopping_list_item_id_supermarket_id_idx" ON "product_prices"("shopping_list_item_id","supermarket_id");
CREATE INDEX "product_prices_family_id_observed_at_idx" ON "product_prices"("family_id","observed_at");
ALTER TABLE "auth_sessions" ADD CONSTRAINT "auth_sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "family_members" ADD CONSTRAINT "family_members_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "families"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "family_members" ADD CONSTRAINT "family_members_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "products" ADD CONSTRAINT "products_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "categories"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "family_products" ADD CONSTRAINT "family_products_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "families"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "family_products" ADD CONSTRAINT "family_products_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "family_supermarkets" ADD CONSTRAINT "family_supermarkets_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "families"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "family_supermarkets" ADD CONSTRAINT "family_supermarkets_supermarket_id_fkey" FOREIGN KEY ("supermarket_id") REFERENCES "supermarkets"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "shopping_lists" ADD CONSTRAINT "shopping_lists_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "families"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "shopping_lists" ADD CONSTRAINT "shopping_lists_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "shopping_list_items" ADD CONSTRAINT "shopping_list_items_shopping_list_id_fkey" FOREIGN KEY ("shopping_list_id") REFERENCES "shopping_lists"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "shopping_list_items" ADD CONSTRAINT "shopping_list_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "product_prices" ADD CONSTRAINT "product_prices_family_id_fkey" FOREIGN KEY ("family_id") REFERENCES "families"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "product_prices" ADD CONSTRAINT "product_prices_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "product_prices" ADD CONSTRAINT "product_prices_supermarket_id_fkey" FOREIGN KEY ("supermarket_id") REFERENCES "supermarkets"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "product_prices" ADD CONSTRAINT "product_prices_shopping_list_item_id_fkey" FOREIGN KEY ("shopping_list_item_id") REFERENCES "shopping_list_items"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "product_prices" ADD CONSTRAINT "product_prices_recorded_by_id_fkey" FOREIGN KEY ("recorded_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
